class BookManagement:
    def __init__(self):
        self.inventory = {}

    def add_book(self, title, quantity=1):
        if self._book_exists(title):
            self._increment_book_quantity(title, quantity)
        else:
            self._set_book_quantity(title, quantity)

    def remove_book(self, title, quantity):
        if self._book_not_available(title, quantity):
            raise ValueError(f"Cannot remove {quantity} of {title}: insufficient quantity or book not found")
        self._decrement_book_quantity(title, quantity)
        if self._book_quantity_is_zero(title):
            self._remove_book_from_inventory(title)

    def view_inventory(self):
        return dict(self.inventory)

    def view_book_quantity(self, title):
        if self._book_does_not_exist(title):
            return 0
        return self._get_book_quantity(title)

    # Private helper methods

    def _book_exists(self, title):
        return title in self.inventory

    def _book_does_not_exist(self, title):
        return title not in self.inventory

    def _increment_book_quantity(self, title, quantity):
        self.inventory[title] += quantity

    def _set_book_quantity(self, title, quantity):
        self.inventory[title] = quantity

    def _decrement_book_quantity(self, title, quantity):
        self.inventory[title] -= quantity

    def _book_quantity_is_zero(self, title):
        return self.inventory[title] == 0

    def _remove_book_from_inventory(self, title):
        del self.inventory[title]

    def _book_not_available(self, title, quantity):
        return self._book_does_not_exist(title) or self._get_book_quantity(title) < quantity

    def _get_book_quantity(self, title):
        return self.inventory[title]

    # Encapsulation methods
    def get_inventory(self):
        return dict(self.inventory)

    def set_inventory(self, inventory):
        self.inventory = dict(inventory)
